const agg = $node["HTTP Request"].json.aggregations;

const reglesRows = $input.all().map(i => i.json);
const descMap = new Map();
for (const r of reglesRows) {
  if (r.rule_name && r.rule_description)
    descMap.set(r.rule_name, r.rule_description.substring(0, 500));
}

function topIps(map, n) {
  return [...map.entries()].sort((a,b) => b[1]-a[1]).slice(0,n)
    .map(([ip,c]) => `${ip} (${c})`).join(", ") || "non renseignées";
}

let texte = "ALERTES DE CORRÉLATION UTMSTACK DES DERNIÈRES 24H\n";
texte += "(source : index OpenSearch v11-alert-* — couche de corrélation UTMStack)\n\n";

texte += "Répartition par sévérité:\n";
for (const b of (agg.par_severite?.buckets || [])) texte += `- ${b.key}: ${b.doc_count}\n`;
texte += "\nRépartition par statut:\n";
for (const b of (agg.par_statut?.buckets || [])) texte += `- ${b.key}: ${b.doc_count}\n`;
texte += "\nRépartition par catégorie MITRE:\n";
for (const b of (agg.par_categorie?.buckets || [])) texte += `- ${b.key}: ${b.doc_count}\n`;

texte += "\n\n=== DÉTAIL PAR RÈGLE DE CORRÉLATION ===\n";
for (const r of (agg.par_regle?.buckets || [])) {
  const sev = r.severite?.buckets?.[0]?.key || "?";
  const cat = r.categorie?.buckets?.[0]?.key || "?";
  const tech = r.technique?.buckets?.[0]?.key || "non spécifiée";
  const sigs = r.signatures_suricata?.buckets || [];

  texte += `\n### ${r.key} (${r.doc_count} alerte(s) au total)\n`;
  texte += `Sévérité déclarée: ${sev} | Catégorie MITRE: ${cat} | Technique: ${tech}\n`;
  if (descMap.has(r.key)) {
    texte += `Description officielle de la règle: ${descMap.get(r.key)}\n`;
  }
  if (sigs.length > 0) {
    texte += "Signatures Suricata sous-jacentes:\n";
    for (const s of sigs) {
      texte += `  - ${s.key} (${s.doc_count} occurrence(s))\n`;
      const ipsMap = new Map();
      for (const ip of (s.ips_source?.buckets || [])) {
        const pays = ip.pays?.buckets?.[0]?.key || "?";
        ipsMap.set(`${ip.key} [${pays}]`, ip.doc_count);
      }
      texte += `    IP sources: ${topIps(ipsMap, 3)}\n`;
      const cibMap = new Map();
      for (const ip of (s.ips_cible?.buckets || [])) cibMap.set(ip.key, ip.doc_count);
      texte += `    Cibles internes: ${topIps(cibMap, 3)}\n`;
    }
  } else {
    texte += "(aucune signature Suricata sous-jacente renseignée pour cette règle)\n";
  }
}

return [{ json: { donnees_brutes: texte } }];

const choix = $json.choices?.[0];
const texte = choix?.message?.content || "(reponse vide ou format inattendu)";
const date = new Date().toISOString().split('T')[0];

return [{ json: {
  synthese: texte,
  date: date
} }];

